        public const string Logo = "";
        const string Logo16 = "";
        const string Ico = "";
        static readonly Dictionary<string, Image> cache = new Dictionary<string, Image>();
        static Image Png(string b) { using (var ms = new MemoryStream(Convert.FromBase64String(b))) using (var im = Image.FromStream(ms)) return new Bitmap(im); }
        public static Image Get(string n) { return Get(n, 20); }
        // px: cỡ cần dùng – 16 cho menu, 20 cho thanh công cụ, từ 24 trở lên lấy bản 32
        public static Image Get(string n, int px)
        {
            if (string.IsNullOrEmpty(n)) return null;
            int s = px <= 16 ? 16 : px <= 24 ? 20 : 32; var d = s == 16 ? D16 : s == 20 ? D20 : D32;
            string k = n + "|" + s; Image i; if (cache.TryGetValue(k, out i)) return i;
            string b; if (!d.TryGetValue(n, out b)) return null;
            try { i = Png(b); } catch { return null; }
            cache[k] = i; return i;
        }
        public static string For(string title, string ic) { string r; return title != null && Rieng.TryGetValue(title, out r) ? r : ic; }
        public static Image LogoImg() { return Png(Logo); }
        public static Image LogoImg(int px) { return Png(px <= 24 ? Logo16 : Logo); }
        // biểu tượng ứng dụng nhiều cỡ (16…64) cho cửa sổ
        public static Icon AppIcon() { using (var ms = new MemoryStream(Convert.FromBase64String(Ico))) return new Icon(ms); }
